INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_057404f10343fbd8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Pakistan Mineral Development Corporation (PMDC) was established in the year _____?', '{"A":"1989","B":"1974","C":"1958","D":"1971","E":"1972"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation PMDC is an autonomous corporation under the administrative control of Ministry of Petroleum and Natural Resources.PMDC founded in 1974.');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_f21d9bb33ff2dca6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Which is the oldest seaport of Pakistan?', '{"A":"Karachi Port","B":"Port Qasim","C":"Gwadar","D":"Pasni","E":"All"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan has three big sea ports named as Karachi Port, Muhammad Bin Qasim port, and Gwadar port. Port of Muhammad Bin Qasim is the oldest port while the Karachi port is the busiest one.');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_aa97c8dc0d9515a8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Broghil Pass connects Pakistan with?', '{"A":"China","B":"Iran","C":"Afghanistan","D":"India"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Broghil Pass connects Pakistan with Afghanistan.Broghol Pass is a high mountain pass that crosses the Hindu Kush mountain range and connects Wakhan District of Badakhshan Province in Afghanistan with Chitral District of Khyber Pakhtunkhwa in Pakistan.');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_f8b08c7a7ad0dc78', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The first Pakistani Cricketer to score a double century in ODI is?', '{"A":"Sarfraz Ahmad","B":"Muhammad Rizwan","C":"Ahmad Shehzad","D":"Fakhar Zaman"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Fakhar Zaman is the first Pakistani cricket player to score a double century in ODIs.He made 210 runs off 156 balls against Zimbabwe (4th ODI at Bulawayo in 2108)He becomes the sixth international batsman to make double-hundreds in ODIs.');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_8a0f9c52082fe6f1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Which community is facing target killing in Baluchistan?', '{"A":"Hazara","B":"Turkmens","C":"Brahuis","D":"Uzbeks"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Targeted suicide attack on the Hazara community killed 79 people. The Hazaras claim that there have been 173 attacks on their community');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_07ed7a5eb5155aaa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Shah Wali Ullah persuaded Ahmad Shah Abdali to fight against?', '{"A":"Sikhs","B":"British","C":"Jews","D":"Marhatas","E":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Shah Wali Ullah (1703-1762) persuaded Ahmad Shah Abdali, He was the founder of the Durrani Empire, to invade India and fight against the Marathas,The Marathas were a powerful Hindu empire at that time.In 1761, Ahmad Shah Abdali, with the support of Shah Wali Ullah, defeated the Marathas in the Third Battle of Panipat.');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_1a9558de7c8e918d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Malala Yousafzai basically belongs to _____?', '{"A":"Hunza","B":"Quetta","C":"Mingora","D":"Multan","E":"Karachi"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation About Malala YousafzaiBorn: 1997Belongs: Mingora, SwatRecieved Noble Prize in 2014She is the youngest Nobel prize laurate United Nations recognized Malala Day On 12 July 2013.');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_30bb6e8b1ec399ff', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'What was the code name of overthrowing the Government of Zulifqar Ali Bhutto?', '{"A":"Operation Midnight jackle","B":"Operation fair play","C":"Operation overload","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Operation Fair Play was the code name for the 5 July 1977 coup by Pakistan Chief of Army Staff General Muhammad Zia-ul-Haq, overthrowing the government of Prime Minister Zulfikar Ali Bhutto.');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_804e25fcf7671c5d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Which organization made a special envoy in 2019 for Kashmir?', '{"A":"OIC","B":"GCC","C":"ASEAN","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation India revoked Article 370 of its constitution on 5 August 2019. Article 370 grants special status to Kashmir.');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_922d1607bfca1f95', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Pakistan Seabed territory grows by 50000 square km in ______?', '{"A":"2009","B":"2015","C":"2019","D":"2022"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan''s seabed territory grew by about 50,000 square kilometers After a UN body accepted Islamabad''s claim for extension of sea limits.');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_8b2497c8b8c9b19a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'PODO and EBDO was promulgated by Ayub Khan to ______?', '{"A":"To get majority","B":"To make strong government","C":"Disqualify the leaders of East Pakistan","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ayub Khan passed EBDO in August 1959Under this, 75 leaders were disqualified for participating in political activities for 8 years (until December 1966).EBDO stands for Electoral bodies dissolution order.');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_6acb919714d1fe03', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Sialkot-Lahore Motorway is called?', '{"A":"M11","B":"M5","C":"M3","D":"M12"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The motorway that connects Sialkot to Lahore is called the M-11 motorway. It''s a 103-kilometer-long north-south motorway in the Punjab region of Pakistan. The motorway opened to traffic on March 18, 2020');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_05822bd2760d8a22', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Gulab Devi hospital was established in 1934 by _____?', '{"A":"Mangal Pandy","B":"Lala Lajpat Rai","C":"Subhash Chandra","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Gulab Devi Chest Hospital is a 1,500 bed semi-private tertiary care chest hospital located in Ferozepur Road, Lahore, Punjab, Pakistan.The hospital was established in 1934 by Indian freedom fighter Lala Lajpat Rai in the memory of his mother, Gulab Devi, who died due to tuberculosis in 1927.');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_e577c84e1d67b13a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'What is the main issue between Pakistan and India?', '{"A":"Law and order issue","B":"Water issue","C":"Kashmir issue","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Since the Partition of British India in 1947, the two countries have been involved in a number of wars, conflicts, and military standoffsThe Jammu and Kashmir regions have been disputed since partition, with Pakistan and India both claiming ownershipIndia–Pakistan relationsPakistanIndiaDiplomatic missionHigh Commission of Pakistan, New DelhiHigh Commission of India, IslamabadND27122022');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_7a566ac6d43858c9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'First census in India was made in the period of ________?', '{"A":"Lord Mayo","B":"Lord Canning","C":"Lord Curzon","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The first modern census in India was conducted during the period of Lord Mayo, who served as the Viceroy and Governor-General of India from 1869 to 1872. The census was conducted in 1871,');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_b4052d06bec9cf75', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Justice Umar Ata Bandial became ______ Chief Justice of Pakistan?', '{"A":"16th","B":"21th","C":"32th","D":"28th"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Justice Umar Ata Bandial became the 28th Chief Justice of Pakistan.He assumed office on February 2, 2022.27th Chief Justice: Justice Gulzar Ahmed29ty Chief Justice: Qazi Faiz Issa');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_74863c71460ac331', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Which place is called the  Jewel of Hindukush?', '{"A":"Balakot","B":"Hazara","C":"Chitral","D":"None of these"}', 'C', '');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_e8a645472ce4b408', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Who played the leading role in drama Waris?', '{"A":"Farhan Ali","B":"Mehboob Alam","C":"Abid Ali","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mehboob Alam as Dilawar has performed in one of the lead roles of WarisDirected by: Nusrat Thakur; Ghazanfer AliWritten by: Amjad Islam AmjadNo. of episodes 13Distributor PTVlanguage: Urducountry of origin: PakistanThe first episode was aired from PTV-Lahore on Saturday 29 December 1979 and the last on 22 March 1980 ND17-1-2023');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_b1514d28a12e1946', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Rawalpindi conspiracy case was attempted coup d''état against against which the government?', '{"A":"Liaquat Ali Khan","B":"Z A Bhutto","C":"Nawaz Sharif","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Rawalpindi Conspiracy (also known as the Rawalpindi Conspiracy Case) The Rawalpindi Conspiracy was an attempted coup d''état against the government of Liaquat Ali KhanAt this time Liaquat Ali Khan, the first Prime Minister of Pakistan, in 1951The hearing of the Rawalpindi Conspiracy Case began on the 14th of June 1951 in Hyderabad JailFaiz Ahmad faiz and Major general Akbar Khan was part of the Rawalpindi Conspiracy CaseND1-5-2023');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_96b293f1fddf4cd9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'In Pakistan, the Chilghoza forests are found in ______?', '{"A":"Murree","B":"Ziarat","C":"Zhob","D":"Karachi","E":"None of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Chilgoza forests are mainly located in the dry temperate zone of Pakistan, where there is less rainfall compared to snowfall.Ziarat is located in Balochistan.');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_acdf15796d053327', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'In which country, Pakistan won the Cricket World Cup 1992?', '{"A":"South Africa","B":"New Zealand","C":"England","D":"Australia"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation About men’s Cricket World Cup 1992Edition: FifthFormat: One Day International (ODI)Venue: Australia & New ZealandFinal held: 25 March 1992Final Venue: MelbourneWinner: Pakistan (First title)Runners-up: EnglandParticipating teams: 09Total Matches: 39Most wickets taken by: Wasim Akram (18 wickets)****');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_56edb8541810ab33', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'OGRA decided fuel prices after how many days?', '{"A":"10","B":"15","C":"30","D":"60"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Oil & Gas Regulatory Authority is an agency of the Government of Pakistan,It is responsible for regulating the oil and gas sector in Pakistan.OGRA was established on March 28, 2002 Its headquarters is located in Islamabad.It was founded by the Federal Government.');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_5b023e4bedb05697', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'What is the new name of Kashmir highway?', '{"A":"Ladak Highway","B":"Poonch Highway","C":"Srinagar Highway","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The new name of Kashmir Highway is Srinagar Highway.This highway is a major east-west highway in Islamabad, Pakistan''s capital territory.It provides quick access through Islamabad and connects the Islamabad International Airport in the west to the E-75 Expressway in the east.The total length of the highway is 25 kilometers, and its width varies from three lanes to five lanes, with five interchanges.');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_95ea26291d342d1b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Which of the following is the biggest Fort in Pakistan?', '{"A":"Ranikot","B":"Ramkot","C":"Rohtas","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ranikot is the biggest Fort in Pakistan**This Fort is present in Sindh.Ranikot Fort is also known as The Great Wall of Sindh and is believed to be the world''s largest fort, with a circumference of approximately 32 kilometers (20 mi).Nawab Wali Mohammad Khan Leghari, made Ranikot fort**Rohtas Fort is the oldest fort in Pakistan');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_15c514f206234bfe', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'In Pakistan, WAPDA stands for _______________?', '{"A":"Water And Process Development Authority","B":"Water And Plant Development Authority","C":"Water And Power Development Authority","D":"Wild And Plant Development Authority"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation WAPDA established through an Act of Parliament in February 1958.WAPDA Headquarters: Lahore*********FIA VU CONSTABLE PAST PAPER 2021');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_87987251ce21c160', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'WAPDA was founded in the year______?', '{"A":"1991","B":"1958","C":"1968","D":"1971","E":"1988"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation WAPDA: Water & Power Development AuthorityWAPDA Headquarters: LahoreWAPDA founded: February 1958');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_45bf3039ad2ff082', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Who was Zia Mohyeddin?', '{"A":"Actor","B":"Singer","C":"Comedian","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Born: June 20, 1931, FaisalabadDied: February 13, 2023 (age 91 years), KarachiSpouse: Azra Mohyeddin (m. 1994)Books: A Carrot is a Carrot: Memories and ReflectionsChildren: 4');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_4b67a2c70799f879', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'On what date "Zindagi App" mobile app was launched?', '{"A":"August  6, 2020","B":"January 6, 2020","C":"May 6, 2020","D":"April 6, 2020"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Zindagi App" mobile app was launched on January 6, 2020 by the then Prime Minister (Imran Khan) of Pakistan.');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_fbdf275d3fa6c991', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Hanns Seidel Foundation (HSF) offers Pakistan students _____?', '{"A":"Scholarships","B":"Life Insurance","C":"Medical help","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation HSF provides full scholarships to talented students who aim to pursue higher education from prestigious German universities.These scholarships not only include generous stipends to cover their education and living expenses but also support the students'' admission and visa processes.');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_7e89a59881dae46c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'In 2022, season of PSL was held entirely in Pakistan for ______ the time.', '{"A":"2nd","B":"1st","C":"3rd","D":"4th"}', 'C', '');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_5a027aeee4d0c495', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'What is the name of the economic corridor signed between China and Pakistan in 2015?', '{"A":"CPEC","B":"PCEC","C":"ECPC","D":"CPEP"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The China-Pakistan Economic Corridor (CPEC) is expected to be fully operational by 2030.The China-Pakistan Economic Corridor (CPEC) is a series of energy and infrastructure projects, some of which connect China’s Xinjiang to Gwadar.Initiated in mid-2013 and formally launched in April 20, 2015.CPEC is generally described as a $46 billion package of Chinese aid.');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_21ee73d9c024b501', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Muhammad Ali Sadpara was a ______?', '{"A":"Cricketer","B":"Traveler","C":"Mountaineer","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Muhammad Ali Sadpara was a Pakistani high-altitude mountaineer. He was part of the team that successfully completed the first winter ascent to the summit of Nanga Parbat in 2016. Born: February 2, 1976, SkarduDied: February 18, 2021, BottleneckDisappeared: 5 February 2021 K2, PakistanBody discovered: July 26, 2021');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_453872465393aa81', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Which of following range is termed as Trans Himalayas?', '{"A":"Hindu kush","B":"Karakoram","C":"Sub Himalayas","D":"Gangdise"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Trans Himalayas are divided into four ranges namely:Ladakh rangeZaskar RangeKarakoram RangeKailash rangeThe Trans Himalaya was named by Swedish explorer Sven Hedin.');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_84384da1135aec72', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Tipu Sultan got martyred on _____?', '{"A":"8th April 1799","B":"8th May 1799","C":"8th June 1799","D":"8th July 1799"}', 'B', '');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_47cac6775b6ed0d0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'In Pakistan term Changa Manga Politics is used for _____?', '{"A":"Kich back","B":"Bribary","C":"Horse-trading","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In Pakistan term, Changa Manga politics is used for horse tradingThe Changa Manga is a planted forest and a wildlife park in Kasur District and Lahore District.Established: 1866the oldest hand-planted forest in the world.the forest covers an area of 48.6 square kilometers (12,000 acres).The name of the forest is derived from an amalgamation of the names of two brother dacoits (bandits), Changa and MangaThe Changa Manga forest can be entered from a road off the N-5 Highway ***');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_29832eed9a190715', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'How many votes required Pakistan to exit from Grey list?', '{"A":"18","B":"12","C":"17","D":"19"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan needs 12 votes out of 39 to exit the ''grey'' list and move to the ''white'' list. To avoid ''black'' list, it needs support of three countries. China, Turkey and Malaysia are its consistent supporters.');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_8225d94dd954184e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Anna Molka Ahmad famous for _______?', '{"A":"Literature","B":"Scientist","C":"Painting","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Anna Molka Ahmad (1917-1994) was a renowned Pakistani artist and painter.She is considered one of the pioneers of modern art in Pakistan.She was the first woman to hold a solo exhibition in Lahore in 1940.Ahmad''s work includes landscapes, portraits, and still-life paintings.She is particularly known for her impressionist style.');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_9fff7317ca481691', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Pakistan Steel Mill was established in the reign of _____?', '{"A":"Zulfiqar Ali Bhutto","B":"Zia-Ul-Haq","C":"Pervez Musharaf","D":"Asif Ali Zardari","E":"Nawaz Sharif"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan Steel Mill in Karachi was founded on July 2, 1973.PM Zulfikar Ali Bhutto laid the foundation stone of Pakistan Steel Mills on December 30, 1973, with the support of the Soviet Union (Russia).An agreement for techno-financial assistance was made between Pakistan and the Soviet Union in 1971.It is the country''s largest industrial undertaking.It has a production capacity of 1.1 million tons of steel.It expandable up to 3.0 million tons per annum.');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_fc50f4d677d1fdc4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Who founded Jamat-e-Islami?', '{"A":"Syed Abul ala maududi","B":"Iqbal","C":"Ahsan","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Jamaat-e-Islami is an Islamist political party which is based in PakistanJamaat-e-Islami''s founder and leader until 1972 was Abul A''la MaududiJamaat-e-Islami was Founded: 26 August 1941.Maududi was the creator and leader of Jamaat-e-Islami, which opposed the partition of India and the creation of PakistanFounded at: Islamia Park, Lahore, PunjabND30-4-2023');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_af655e1f68e7a684', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'When was the Communist Party banned in Pakistan?', '{"A":"1999","B":"1950","C":"1954","D":"1966"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The party continued its political activities in a clandestine way soon after formation. It was banned in July 1954.');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_1d6d967f384ca9ff', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'When Kalat join Pakistan?', '{"A":"December 1948","B":"March 1949","C":"March 1950","D":"March 1948"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Kalāt or Qalāt historically known as QīqānQalat is a district in BalochistanKalat districts of Balochistan Province are predominantly Brahui-speakingKalat join Pakistan on 27 March 1948Kalat is known locally as Kalat-e-Brahui and Kalat-e-Sewa Kalat is the capital of the Kalat District Kalat is known for Juniper old trees, the Moro RiveND21-2-2023');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_8b4c8f689d735876', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Karakoram highway is denoted by', '{"A":"N-25","B":"N-35","C":"N-55","D":"None"}', 'B', '');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_62f837d929551b72', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Any individual, firm, organization and department involved in printing displaying and circulating incorrect version of map of Pakistan is liable to _______?', '{"A":"5 year imprision","B":"5 million fine","C":"Both A and B","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation According to Pakistani law, any individual, firm, or organization involved in displaying or circulating an incorrect version of Pakistan''s map can face both 5 years of imprisonment and a fine of 5 million PKR as a penalty.');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_daa387220fb5af54', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The Foreign Policy of Pakistan is _____?', '{"A":"Regionalism","B":"Alliance Policy","C":"Bilateralism","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan''s foreign policy is primarily based on bilateral relations.It aiming to maintain cooperative ties with individual countries based on mutual interests.This approach allows Pakistan to establish independent foreign relations with diverse nations.');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_a022077196b05bf5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Vaccination program of Pakistan is _____?', '{"A":"CPI","B":"EPI","C":"DPI","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Expanded Program on Immunization (EPI) in Pakistan protects against eight vaccine-preventable diseases and immunizes children below 23 months of age.');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_64a95ffc90eb7007', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Muslims members participated in Shimla conference?', '{"A":"35","B":"38","C":"33","D":"45"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Simla Conference Presided by Lord WavellThe Simla Conference of 1945 was a meeting between:the Viceroy of India Lord Wavell and the major political leaders of British Indiaat the Viceregal Lodge in Simla**35 Muslim members participated in the Shimla conferencesShimla agreement was signed in 1972The Simla Agreement was signed by Prime Minister Indira Gandhi and President Zulfikar Ali Bhutto of Pakistan.ND21-2-2023');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_d3b5cd2c24be33b1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Which  modern country erstwhile Sassanid Empire?', '{"A":"Iran","B":"Persian","C":"Greece","D":"Rome"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Sassanid Empire corresponds to the modern country of Iran.The Sassanid Empire (224–651 AD) was the last pre-Islamic Persian empireRuling over much of what is now modern-day Iran as well as parts of Iraq,');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_c3792b9078744b46', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Malala Yousafzai graduated from which university?', '{"A":"Cambridge","B":"Oxford","C":"Warwick","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Malala Yousafzai, the education campaigner who was shot by the Taliban. She graduated from the University of Oxford in the United Kingdom with a philosophy, politics and economics degree in 2021.Gul Makai is a drama based on the autobiography of Malala Yousafzai.');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_e0a7828fe69d0ae4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Which turkish leader established Kingdom in Sub-continent?', '{"A":"Babar","B":"Qurub ud din aibak","C":"Ahmad shah Abdali","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Qutb ud-Din Aibak, was a general of the Ghurid king Muhammad Ghori. He became the ruler of an independent kingdom that evolved into the Delhi Sultanate ruled by the Mamluk dynasty. Born: 1150, Turkestan, KazakhstanDied: November 14, 1210, Lahore');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_2bc10038e90de645', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The population of Pakistan under the age of 35 is _____?', '{"A":"65%","B":"55%","C":"70%","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation About 70% of Pakistan''s population is under the age of 35. Here''s a breakdown of Pakistan''s population by age group:0–4 years: 12.4%5–12 years: 19.0%13–17 years: 11.0%18–24 years: 13.8%25–34 years: 15.5%35–44 years: 11.0%45–54 years: 7.4%55–64 years: 5.5%65 and above: 4.4%Pakistan''s median age is 20.7 years old.The country has a high growth rate of 2.5%.');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_a363c358b67380e3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'India took up the case of Kulbushan Jhadav in?', '{"A":"International Criminal Court","B":"European Court of Justice","C":"International Court of Justice","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation On 8 May 2017, India commenced these proceedings before the ICJ alleging that Pakistan had committed a breach of the VCCR 1963 by failing to grant immediate consular access in respect of Commander Jadhav, and alleging that the Military Court procedure was flagrantly unfair.');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_1d505763c91c8460', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Fatima Bhutto is the daughter of _____?', '{"A":"Murtaza Bhutto","B":"Zulfiqar Ali Bhutto","C":"Ghanwa Bhutto","D":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Fatima Bhutto was a columnist & writer. Murtaza Bhutto was the brother of Benazir Bhutto.Bhutto was born on 29 May 1982 to Murtaza Bhutto.An Afghan mother, Fauzia Fasihudin Bhutto, the daughter of Afghanistan''s former foreign affairs official in Kabul. Her father was in exile during the military regime of General Zia-ul-Haq.');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_1aee7af3ebb15519', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'When Maulana Muhammad Ali Johar issued Comrade Newspaper from Kolkata?', '{"A":"14 Jan 1910","B":"14 Jan 1912","C":"14 Jan 1911","D":"14 Jan 1913"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Comrade was a weekly English-language newspaper Mohammad Ali Jauhar published it between 1911 from Calcutta Additional information:He moved to Delhi in 1912 and launched an Urdu-language daily newspaper Hamdard there in 1913.');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_455ff49126102fb8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'In which year was the Women Protection Authority established?', '{"A":"2017","B":"2018","C":"2019","D":"2020"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Women Protection Authority was established on 25th March 2017.It was formally inaugurated by the Chief Minister of Punjab.To protect and promote women''s rights and provide support against violence.');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_6167ca865a77297f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Wadiya Mandar Scheme is related to ______?', '{"A":"Education","B":"Taxes","C":"Equality","D":"None of these"}', 'A', '');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_5f87aeda2a7fd188', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'In which year the MAO College was founded?', '{"A":"1876","B":"1875","C":"1877","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Established: 1877Full Form: Muhammadan Anglo-Oriental CollegeFounder: Sir Syed Ahmad KhanLocation: Aligarh, IndiaConverted into University: 1920 (Aligarh Muslim University)Additional information:School Established: 1875Intermediate Classes Started: 1878B.A. Classes Started: 1881Inaugurated by: Lord LyttonFirst Headmaster of M.A.O. School: Henry SiddonsLast verified on 10-07-2026');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_86a29e8bf4c3237d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Who originally sung Akhian nu rehn day?', '{"A":"Meesha","B":"Reshman","C":"Nazia Hassan","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Akhian Noon Rehn De Akhian De Kol Kol is a folk song originally sung by Reshman who is a famous Pakistani singer.');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_1d5eb44a1050dcba', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Shiwaliks are ______ part of Himalayas.', '{"A":"Eastern","B":"Southernmost","C":"Northernmost","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Siwalik Range, also called Siwalik Hills or Outer Himalayas, sub-Himalayan range of the northern Indian subcontinent.');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_46cc457a15558c82', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Which is not a Pakistani Actor?', '{"A":"Muhammad Ali","B":"Nawaz Uddin Siddiqui","C":"Waheed Murad","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Nawazuddin Siddiqui is an Indian actor known for his work in Hindi cinema.');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_f3c5f16a64595084', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Nandana Fort is situated in _______?', '{"A":"Jhelum","B":"Lahore","C":"Rawalpindi","D":"Multan"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Nandana Fort, located near the Salt Range in Jhelum, Punjab.It is historically significant for being the site where Al-Biruni measured the Earth''s circumference during the 11th century.');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_088f05b093d715ef', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'When first Indian civil servant was inducted in government?', '{"A":"1861","B":"1862","C":"1863","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Satyendranath Tagore was an Indian Bengali civil servant, poet, composer, writer, social reformer and linguist from Kolkata, West Bengal. He was the first Indian who became an Indian Civil Service officer in 1863.He was a member of Bramho Samaj.');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_6551a216bbb441c1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Where is Bahauddin Zakariya University located?', '{"A":"Multan, Punjab, Pakistan","B":"Lahore Punjab, Pakistan","C":"Karachi, Sindh, Pakistan","D":"Haydarabad, Sindh, Pakistan"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Bahauddin Zakariya University''s (BZU) main campus is located in Multan, Pakistan. BZU was founded in 1975 as Multan University andBZU is the 2nd largest university in Punjab. It was renamed in 1979 in honour of a Sufi saint Baha-ud-din Zakariya (1171-1262).');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_cf1646c9db979b8b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'In July 1951 Pakistan and France tied for _____?', '{"A":"Economic Ties","B":"To open its Embassies","C":"Mutual Trade","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The foreign relations between Pakistan and France were first established on 31 July 1951 when both countries agreed to open embassy services in each countries. France was one of the first non-Muslim state to recognize Pakistan.');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_be3d64d34181723b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The Karakoram Highway being contrasted with the assistance of the Chines government, was completed in?', '{"A":"1972","B":"1974","C":"1976","D":"1979"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Karakoram Highway being contrasted with the assistance of the Chines government was completed in 1979***Karakoram highway is also known as N-35The Karakoram Highway starts from Hassan Abdal.Karakoram highway was completed in 1979.its length in Pakistan is 1300 km.The same Continues with the name China National Highway 314 (G314) in China');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_877e3fcc593ef302', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Who opposed Nehru report?', '{"A":"All parties conference","B":"Jinnah","C":"Congress","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Nehru Report was published on August 28, 1928, at the Lucknow conference of all the parties.the draft constitution was prepared which was called the “Nehru Committee Report“.The Nehru Report was a memorandum to appeal for new dominion status and a federal set-up of government for the constitution of India.chaired by Motilal Nehru with his son Jawaharlal Nehru acting as a secretary.Jinnah Voted against this report.And represented 14 points in the reply to Nehru Report*******ND19-3-2023*******VU CBT FIA SI ASI PAPER 13-12-2021');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_b5c582620ee1fb37', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Which is the largest of energy in Pakistan?', '{"A":"Thermal","B":"Hydel","C":"Nuclear","D":"Solar"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan''s current energy mix roughly 68% is based on thermal sources like:High-speed diesel, Furnace oil, Heavy fuel oil, Coal,Natural gas.');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_3ea5fcd0ea7ca0fe', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Tochi Pass connects ________?', '{"A":"Dir with Bannu","B":"Peshawar with Bannu","C":"Ghazni with Bannu","D":"Ghazni with Kohat"}', 'C', '');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_4aca799d90c70de8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Sassi Punnu is a story from ____?', '{"A":"Punjabi folklore","B":"Sindhi folklore","C":"Balochi folklore","D":"Pashto folklore"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sassi Punnu is a legendary tale from Sindhi folklore.Hashim Shah was a sufi poet and Punjabi writer.Sassi is known as Princess of Hope.');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_b450731aa6e1a5a0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Dr Abdus Salam of Pakistan was one of the contributed of the unification of:', '{"A":"Electromagnetic force and gravitational force","B":"Electromagnetic force and weak nuclear force","C":"Gravitational force and weak nuclear force","D":"None of these"}', 'B', '');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_a75a64e333fd3496', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Which of the following is not a social issue in Pakistan?', '{"A":"Constitutional Crisis","B":"Illiteracy","C":"Poverty","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation While Pakistan has faced several constitutional crises in its history, it is not a persistent social issue.In contrast, illiteracy and poverty are significant social issues impacting the population in Pakistan.');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_cc99e2ab932ff31b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Which famous musical personality got pride of performance in 2005?', '{"A":"Rahat Fatiah","B":"Arif Lohar","C":"Amanat Ali","D":"Humaira Arshad"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The awards were received by the winners on 23 March 2005Name Arif LoharField ArtsSpecialization folk musicCountry PunjabProvince Pakistan');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_e1c90a68ab5a49ea', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Shah Abdul Latif Bhittai belongs to which Sufi Silsila?', '{"A":"Naqshbandi","B":"Chishti","C":"ldrisiyya","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Shah Abdul Latif Bhittai belongs to Naqshbandi Sufi Silsila.Shah Abdul Latif Bhittai, a renowned Sindhi Sufi poet, lived in the 18th century (1689–1752).His poetry, particularly in Shah Jo Risalo, reflects deep spirituality and the culture of Sindh.Shah Abdul Latif Bhittai, was a Sindhi Sufi mystic and poet from Pakistan.Greatest poet of the Sindhi language. Born: November 18, 1689, HalaDied: December 21, 1752, Bhit ShahPlace of burial: Bhit ShahNationality: Indian, Pakistani');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_75afc2ad3367f5d4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Pakistan won its first men’s Cricket World Cup 1992 under the captaincy of which of the following?', '{"A":"Waseem Akram","B":"Muhammad Younas","C":"Imran Khan","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Imran Khan was the captain of the Pak Cricket team in the 1992 World Cup.Key points about Cricket World Cup 1992:Edition: FifthFormat: One Day International (ODI)Venue: Australia & New ZealandFinal held: 25 March 1992Final Venue: MelbourneWinner: Pakistan (First title)Runners-up: EnglandParticipating teams: 09Total Matches: 39Most wickets taken by: Wasim Akram (18 wickets)');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_e839e0e85b60fbac', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The former World Heavyweight Boxing Champion, Muhammad Ali, was suffering from _____?', '{"A":"Diabetes","B":"Parkinson","C":"Hepatitis","D":"Hypertension"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation World Heavyweight Boxing Champion Muhammad Ali was diagnosed with Parkinson''s disease in 1984.');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_b016d8d6d9e72bc4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Who was the first captain of Pakistan Women''s Cricket ODI and Test matches?', '{"A":"Sana Mir","B":"Shazia Khan","C":"Urooj Mumtaz","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Shaiza Khan was the first captain of Pakistan Women''s Cricket team, leading the team in both ODI and Test matches.She was a pioneering figure in women''s cricket in Pakistan and played a key role in establishing the team.The first captain of the Pakistan women''s T20 team was Sana Mir.She led the team in their first T20 match in 2009.');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_743e4ef02690ac1a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'When Quetta was devastated by an earthquake?', '{"A":"1933","B":"1935","C":"1937","D":"1939"}', 'B', '');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_eb6adc0c7df72c24', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Pakistan People''s Party (PPP) was established in which year?', '{"A":"1964","B":"1967","C":"1960","D":"1966"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan People''s Party (PPP) was founded by Zulfikar Ali Bhutto.Established on November 30, 1967.');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_315fef452759cb3a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Founder of Lodi Dynasty was _____?', '{"A":"Malik Sultan","B":"Darya Khan","C":"Bahlul Khan Lodi","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Bahlul Khan Lodhi was the founder of the Lodhi dynasty of India (1451-1526)Bahlul Khan Lodhi was the founder of the Lodhi dynasty when he replaced the Sayyid dynasty.By the end of the 15th century, Bahlul Lodi firmly established the Lodi dynasty The Lodhi dynasty It was the fifth and final dynasty of the Delhi SultanateND07-3-2023');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_7323235d190af3b5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Aligarh University was established in ______?', '{"A":"1877","B":"1920","C":"1857","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Muhammadan Anglo-Oriental College was founded by Sir Syed Ahmad Khan in 1875, initially as a primary school, with the intention of turning it into a college-level institution.In 1877, the school was raised to college level.Lord Lytton, the Viceroy of India at the time, laid the foundation stone of the Muhammadan Anglo-Oriental College (MAO College) on January 8, 1878. The college was later upgraded to Aligarh Muslim University (AMU) in 1920.');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_a6d2c9af600ff748', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Nizam-e-Mustafa movement was carried in the year?', '{"A":"1972","B":"1977","C":"1993","D":"1997"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The System of the Prophet Muhammad. Nine-party popular movement in Pakistan begun by the Jamaat-i Islami in 1977 to overthrow the secular government of Zulfikar Ali Bhutto and establish an Islamic system of government in Pakistan. The movement was eclipsed after the military coup of Zia-ul-Haq .');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_58c9526adb989ebf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Pakistan’s first coin was issued on _____?', '{"A":"6th june 1949","B":"3rd June 1948","C":"6th January 1948","D":"3rd January 1948","E":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan’s first coin was issued on 3rd January 1948The word Pakistan was first introduced by Choudhry Rahmat Ali. on 28 January 1933,The first coin of Pakistan was designed by Brandley**ND05-12-2022.16.2022,4-1-2023');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_3ea22b628af2ed0a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Headquarter of FBR is located at _______?', '{"A":"Islamabad","B":"Karachi","C":"Lahore","D":"Quetta"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation FBR operates through tax inspectors that keep tax evaders under surveillance and perform special tasks for FBR Headquarters.');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_bb6e87f9f76144f0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'When did Muhammad Bin Qasim defeat Raja Dahir?', '{"A":"711 A.D","B":"713 A.D","C":"714 A.D","D":"712 A.D"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Raja Dahir was the last Hindu ruler of Sindh in present-day Pakistan.In 712 CE his kingdom was invaded by the Umayyad Caliphate led by Muhammad bin Qasimwhere Dahir died while defending his kingdom.Aror was the capital of King Dahir******راجہ داہر موجودہ پاکستان میں سندھ کے آخری ہندو حکمران تھے۔ 712عیسوی میں اس کی سلطنت پر اموی خلافت نے حملہ کیا جس کی قیادت محمد بن قاسم کر رہے تھے۔جہاں داہر اپنی سلطنت کا دفاع کرتے ہوئے مر گیا۔');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_358b432d7ddc081c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'What made Sir Syed Ahmad khan conclude that Hindus and Muslims could not work together anymore?', '{"A":"War of Independence 1857","B":"Congress behavior","C":"Hindi-Urdu Controversy","D":"Issue of Muslim University"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hindi Urdu controversy started in began in the 1860s and continued right up to Independence.');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_b0ed4fd297cc2c60', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Kulbhushan Jadhav death sentence was suspended by _____?', '{"A":"Lahore High Court","B":"International Court of Justice","C":"UN Security Council","D":"Supreme court of Pakistan"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation According to reports, the world court said that Kulbhushan Jadhav''s death sentence should remain suspended until Pakistan effectively reviews and reconsiders the decision, and granted consular access to India.Kulbhushan Jadhav death sentence was suspended in 2019');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_28c118d25349cb70', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'What is the name of Islamic constitutional organization of the Government of Pakistan?', '{"A":"Pakistan Sharia Council","B":"Islamic Ideology council","C":"Islamic economic council","D":"None of the these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Council of Islamic Ideology is a constitutional body of Pakistan, responsible for giving legal advice on Islamic issues to the government and the Parliament. Founded: August 1, 1962Headquarters: Islamabad');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_7f3c8ed9d4cd8400', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Which Pakistani actor worked in Indian movie Mom?', '{"A":"Adnan Siddique","B":"Adnan Ahmad","C":"Adnan Ahmad","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Adnan Siddique is a Pakistani actor who worked in the Indian movie "Mom" (2017) alongside Sridevi, Akshaye Khanna, and Nawazuddin Siddiqui.He played the role of Sridevi''s husband in the film.');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_82ddcf9d663cf718', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Pakistan won only one gold medal in which sports of commonwealth game 2018?', '{"A":"Tennis","B":"Hockey","C":"Badminton","D":"Wrestling"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan won its only gold medal in Wrestling at the 2018 Commonwealth Games, which were held on the Gold Coast, Australia.Muhammad Inam Ahmed won the gold medal in the men''s freestyle 86 kg event.');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_64857e035ef09538', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Pakistan joined the atomic club on _____?', '{"A":"28 May 1998","B":"28 May 1999","C":"28 May 1997","D":"28 May 1996"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Date: 28 May 1998Pakistan conducted nuclear tests at the Chagai Hills (Balochistan)Codenamed "Chagai-I"It was a response to India''s nuclear tests (Pokhran-II) earlier that month (May 11 & 13, 1998)Pakistan became the 7th country in the world to possess nuclear weaponsThe day is commemorated as Youm-e-Takbeer (National Day of Grandeur)Last updated 13 August 2026 by NA');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_5fea1cf04bedcac9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'When Quetta destroyed by Earthquake in 1935?', '{"A":"28 May","B":"17 May","C":"1 May","D":"31 May"}', 'D', '');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_da426f5695f98a2b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Pakistan is considered bridge between _______?', '{"A":"Gulf and South Asia","B":"Central Asia and South Asia","C":"East Asia and South Asia","D":"All of the above"}', 'D', '');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_c31c2df4ca45cdea', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Samjhauta express bomb blast occur in which year?', '{"A":"February, 2007","B":"February, 2008","C":"February, 2009","D":"February, 2010"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation On 18 February 2007, 68 innocent passengers, including over 40 Pakistani nationals, lost their lives in a terrorist attack on Lahore-bound Samjhauta Express train.The attack took place on India''s soil.The Samjhota Express was a train running between Delhi, India, and Lahore, Pakistan.');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_8d07e2008bfb8c2b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'First International Flight of PIA was taken on ____?', '{"A":"17 June 1953","B":"7 June 1956","C":"25 May 1953","D":"1 February 1955"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan International Airlines (PIA) took its first international flight on February 1, 1955It is the flag carrier of Pakistan.Headquarter: KarachiFirst name: Orient airways');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_c1e07bdb69d25485', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The Edhi Foundation has the world''s largest ____?', '{"A":"Volunteers Community","B":"Mediacal Facility","C":"Food Kitchen","D":"Ambulance Service"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Edhi Foundation is a non-profit social welfare organization based in Pakistan. It was founded by Abdul Sattar Edhi in 1951. Headquarters of Edhi Foundation located in Karachi.');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_e8553d219c134a03', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Lala Lajpat Rai was a famous Punjabi leader. He was associated with _______?', '{"A":"Dev Samaj","B":"Arya Samaj","C":"Unionist Party","D":"All India Muslim League"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Lajpat Rai was a heavyweight veteran leader of the Indian Nationalist Movement.He was led by the Indian National Congress, Hindu reform movements and Arya Samaj.He was the founder of Arya Samaj. He died on November 17, 1928');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_6e965847e456f02a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Who was the first Pakistani doctor who lost his life due to COVID-19 infection and was posthumously awarded Nishan-e-Kashmir on March 27, 2020?', '{"A":"Muhammad Usama","B":"Usama Riaz","C":"Usman Raza","D":"Raza Usman"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Riaz died on 23 March 2020, from COVID-19 complications at the age of 26.Riaz was the first Pakistani doctor to die from the virus.On 27 March 2020, he was posthumously awarded the Nishan-e-Kashmir, the highest award of the state, by Prime Minister of Azad Kashmir for his services.');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_5e212d5a86884476', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Due to Geostrategic position, no peace is possible in Afghanistan without the active support and cooperation of ______?', '{"A":"India","B":"Iran","C":"Pakistan","D":"China"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan shares a long border with Afghanistan and has significant geopolitical influence in the region. Due to its strategic location, Pakistan plays a crucial role in Afghanistan''s stability and security.Historically, Pakistan has had close ties with various Afghan groups and has been involved in Afghan affairs.');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_8e0d570f659ca03e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'In the context of Pakistan''s political and judicial history what does PCO stands for?', '{"A":"Provisional Court Organization","B":"Pakistan Constitutional Ordinance","C":"Provincial Constitutional Order","D":"Pakistan''s Courts Ordinance"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In Pakistan''s political and judicial history, PCO stands for Provincial Constitutional Order.It issued during military regimes to suspend or amend the constitution, often affecting the judiciary.');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_7b6437fd703f852a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The Lucknow pact granted the right of Separate Electorates to the _____?', '{"A":"Hindus","B":"Sikhs","C":"Muslims","D":"Christians"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation On 1st October 1906, a Muslim political delegation led by Aga KhanMet with the Viceroy of India to demand a separate electorate for Muslims.This delegation played a crucial role in the establishment of the Muslim League in 1906');
INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation) VALUES ('mcq_tp_8b74a92134c67bd6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Which one was signed on 8 April 1950?', '{"A":"CENTO","B":"Tashkent Declaration","C":"SEATO","D":"Liaqat Nehru Pact","E":"Colombo Plan"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Nehru-Liaquat Pact, also known as the Delhi PactIt was a bilateral treaty between India and Pakistan It was signed on 08-April-1950.Expiration: 8 April 1956Signatories:Jawahar Lal Nehru(Prime Minister of India) Liaquat Ali Khan (Prime Minister of Pakistan)');
